INSERT INTO course_subjects (subject_id, course_id, subject_name) VALUES
  ('ab200000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000002', 'Linear Algebra Prerequisites'),
  ('ab200000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000002', 'Discrete-Time Fourier Series'),
  ('ab200000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000002', 'Continuous-Time Fourier Series and Properties'),
  ('ab200000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000002', 'Continuous-Time Fourier Transform and Convergence Conditions'),
  ('ab200000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000002', 'Discrete-Time Fourier Transform'),
  ('ab200000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000002', 'Gibbs Phenomenon and Transform Properties'),
  ('ab200000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000002', 'Fourier Transform of Periodic Signals'),
  ('ab200000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000002', 'Plancherel and Parseval Theorems, Duality'),
  ('ab200000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000002', 'Frequency Domain System Analysis'),
  ('ab200000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000002', 'Communication and Basic Modulation'),
