INSERT INTO course_subjects (subject_id, course_id, subject_name, subject_description) VALUES
  ('ab000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000003', 'Power and Ethics in Jewish Law', 'Halachic sources on the limits of authority and coercion'),
  ('ab000000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000003', 'Military Ethics in Jewish Thought', 'War, self-defense, and moral constraints in rabbinic literature'),
  ('ab000000-0000-0000-0000-000000000011', 'c0000000-0000-0000-0000-000000000003', 'Political Power in Jewish History', 'Case studies of authority and resistance in Jewish historical contexts');
INSERT INTO course_subjects (subject_id, course_id, subject_name, subject_description) VALUES
  ('ab400000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000004', 'יסודות המוליכים למחצה', 'היכרות עם מהות החומר, המבנה הגבישי של סיליקון, קשרים קוולנטיים ומצבי ערכיות.'),
  ('ab400000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000004', 'מבנה פסי אנרגיה', 'הבנת פסי הולכה וערכיות, פער האנרגיה, וההבדלים הנובעים מכך בין מוליכים, מבודדים ומוליכים למחצה.'),
  ('ab400000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000004', 'מנגנוני הולכה וזרמים', 'לימוד על יצירה תרמית של זוגות אלקטרון-חור, מוביליות של נושאי מטען, וההבדלים בין זרם סחיפה לזרם דיפוזיה.'),
  ('ab400000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000004', 'צומת pn', 'ניתוח הצומת בשיווי משקל ואזור המחסור, היכרות עם מודלים של דיודה וחישוב קיבול הצומת תחת ממתח אחורי.'),
  ('ab400000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000004', 'פיזיקה של טרנזיסטור ה-MOS', 'הכרת מתח הסף ואפקט הגוף, ניתוח אזורי העבודה של הטרנזיסטור (קיטעון, ליניארי ורוויה) והבנת הקיבולים הפרזיטיים.'),
  ('ab400000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000004', 'טכנולוגיית ייצור ו-Layout', 'סקירת תהליך הייצור של CMOS, חוקי תכנון (DRC), הקשר למימוש הפיזי ותופעת ה-Latchup.'),
  ('ab400000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000004', 'מבוא למערכות דיגיטליות', 'השוואה בין אנלוג לדיגיטל והגדרת שערים לוגיים דיגיטליים, כולל רמות לוגיות ותכונת ההתחדשות.'),
  ('ab400000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000004', 'מטריקות סטטיות', 'הגדרת עקומת תמסורת המתח (VTC), רמות מתח קריטיות ושולי רעש (Noise Margins) והשפעתם על יציבות המערכת.'),
  ('ab400000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000004', 'המהפך (Inverter) בטכנולוגיית CMOS', 'ניתוח מבנה המהפך הסטטי, פעולתו כמתג, אזורי העבודה של הטרנזיסטורים וסף המיתוג שלו.'),
  ('ab400000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000004', 'מטריקות דינמיות ותזמון', 'בחינת זמני השהיה, התפשטות, עלייה ונפילה, וכן השפעת קיבול המוצא על מהירות המעגל הלוגי.'),
  ('ab400000-0000-0000-0000-000000000011', 'c0000000-0000-0000-0000-000000000004', 'צריכת הספק (Power Dissipation)', 'חישוב צריכת ההספק הסטטית והדינמית במעגל, כולל רכיב ה-Short Circuit ונוסחת ההספק הכולל.'),
  ('ab400000-0000-0000-0000-000000000012', 'c0000000-0000-0000-0000-000000000004', 'שערים לוגיים מורכבים ב-CMOS', 'תכנון רשתות Pull-Up ו-Pull-Down למימוש שערים מורכבים (כגון NAND ו-NOR), קביעת גדלי טרנזיסטורים ואופטימיזציה.'),
  ('ab400000-0000-0000-0000-000000000013', 'c0000000-0000-0000-0000-000000000004', 'פיזיקה ליישומים אנלוגיים', 'ניתוח מעמיק של פעולת הטרנזיסטור באזור הרוויה כמקור זרם או מגבר, והבנת תופעת שינוי אורך התעלה.'),
  ('ab400000-0000-0000-0000-000000000014', 'c0000000-0000-0000-0000-000000000004', 'מודל אות קטן (Small Signal Models)', 'פיתוח מודל אות קטן עבור טרנזיסטור ה-MOS והבנת השפעת אפקט הגוף (Bulk gm) ביישומים אלו.'),
  ('ab400000-0000-0000-0000-000000000015', 'c0000000-0000-0000-0000-000000000004', 'תגובת תדר וקיבולים', 'בחינת ההשפעה של קיבולים פרזיטיים על ביצועי המעגלים האנלוגיים בתדרים גבוהים (AC).');
